// Sub-WF D: Event Classifier
// Input: a raw Google Calendar event object from the Execute Workflow Trigger
//
// IMPORTANT: When called via Execute Workflow "Using Fields Below", nested objects
// (start, end, attendees, conferenceData) arrive as JSON strings, not objects.
// The parsing below handles both cases (string or object) defensively.
const raw = $json;
const event = {
  id: raw.id,
  summary: raw.summary,
  location: raw.location,
  start: typeof raw.start === 'string' ? JSON.parse(raw.start) : (raw.start || {}),
  end: typeof raw.end === 'string' ? JSON.parse(raw.end) : (raw.end || {}),
  attendees: typeof raw.attendees === 'string' ? JSON.parse(raw.attendees) : raw.attendees,
  conferenceData: typeof raw.conferenceData === 'string' ? JSON.parse(raw.conferenceData) : raw.conferenceData
};

// --- Check 1: All-day event ---
// All-day events have event.start.date (a date string like "2025-06-15")
// but NOT event.start.dateTime (which has a full timestamp)
if (event.start && event.start.date && !event.start.dateTime) {
  return { skip: true, reason: "all-day event" };
}

// --- Check 2: Declined event ---
// Google Calendar API includes an attendees array; the user's own entry has "self": true
if (event.attendees && Array.isArray(event.attendees)) {
  const selfEntry = event.attendees.find(a => a.self === true);
  if (selfEntry && selfEntry.responseStatus === "declined") {
    return { skip: true, reason: "declined" };
  }
}

// --- Check 3: No location ---
const location = (event.location || "").trim();
if (!location) {
  // Check if the event has a conferenceData (Google Meet / Zoom link added via calendar UI)
  const hasConference = event.conferenceData && event.conferenceData.conferenceSolution;
  if (!hasConference) {
    // No location AND no video conference — skip
    return { skip: true, reason: "no location" };
  }
}

// --- Determine is_online ---
// Online if location contains video meeting keywords OR has conferenceData
const locationLower = location.toLowerCase();
const onlineKeywords = ["zoom", "meet", "teams", "webex", "slack", "hangout"];
const hasOnlineKeyword = onlineKeywords.some(kw => locationLower.includes(kw));
const hasConferenceData = event.conferenceData && event.conferenceData.conferenceSolution;
const is_online = hasOnlineKeyword || !!hasConferenceData;

// --- Determine is_tentative ---
let is_tentative = false;
if (event.attendees && Array.isArray(event.attendees)) {
  const selfEntry = event.attendees.find(a => a.self === true);
  if (selfEntry && selfEntry.responseStatus === "tentative") {
    is_tentative = true;
  }
}

// --- Determine force_car ---
const title = event.summary || "";
const force_car = title.toLowerCase().includes("[car]");

// --- Determine dress_cap ---
// [dress:N] or [N] in title caps dressed reminder intervals to ≤ N minutes.
// e.g. "Gym [30]" with DRESS_REMINDER_INTERVALS=90,60,30,15 → only 30 and 15 fire.
let dress_cap = 0; // 0 = no cap, use all intervals
const dressTagMatch = title.match(/\[dress:(\d+)\]/i);
const bareNumberMatch = title.match(/\[(\d+)\]/);
if (dressTagMatch) {
  dress_cap = parseInt(dressTagMatch[1], 10);
} else if (bareNumberMatch) {
  dress_cap = parseInt(bareNumberMatch[1], 10);
}

// --- Handle multi-day events ---
// Google Calendar API returns individual instances for recurring events (if singleEvents=true)
// For multi-day events spanning multiple days, we only process today's portion
let adjusted_start = event.start.dateTime || event.start.date;
let adjusted_end = event.end.dateTime || event.end.date;

// --- Return classification ---
return {
  skip: false,
  is_online: is_online,
  is_tentative: is_tentative,
  force_car: force_car,
  dress_cap: dress_cap,
  adjusted_start: adjusted_start,
  adjusted_end: adjusted_end,
  location: is_online ? null : location,
  title: title,
  event_id: event.id
};
